const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];const reduceMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;/* loader replaced by intro-loader */const menuButton=$('.menu-toggle'),menu=$('.site-menu');function closeMenu(){menu.classList.remove('open');document.body.classList.remove('menu-open');menuButton.setAttribute('aria-expanded','false')}menuButton.addEventListener('click',()=>{const open=!menu.classList.contains('open');menu.classList.toggle('open',open);document.body.classList.toggle('menu-open',open);menuButton.setAttribute('aria-expanded',String(open))});$$('.site-menu a').forEach(l=>l.addEventListener('click',closeMenu));const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');revealObserver.unobserve(entry.target)}}),{threshold:.12});$$('.reveal').forEach(el=>revealObserver.observe(el));const rows=$$('.project-row'),previews=$$('.project-preview');function activateProject(name){rows.forEach(r=>r.classList.toggle('active',r.dataset.project===name));previews.forEach(p=>p.classList.toggle('active',p.dataset.preview===name))}rows.forEach(row=>{row.addEventListener('mouseenter',()=>activateProject(row.dataset.project));row.addEventListener('focus',()=>activateProject(row.dataset.project));row.addEventListener('touchstart',()=>activateProject(row.dataset.project),{passive:true})});$$('[data-project-jump]').forEach(link=>link.addEventListener('click',()=>setTimeout(()=>activateProject(link.dataset.projectJump),350)));const capabilityContent={ai:{description:'Intelligent applications shaped by semantic understanding, classification, and practical automation.',tags:['SCIKIT-LEARN','SENTENCE TRANSFORMERS','NLP','FASTAPI'],mark:'ML'},web:{description:'Full-stack products connecting clean interfaces to structured APIs, business logic, and data.',tags:['REACT','VITE','NODE.JS','EXPRESS','PRISMA','POSTGRESQL'],mark:'</>'},vision:{description:'Real-time systems that understand faces, hands, gestures, and visual signals from the world.',tags:['OPENCV','MEDIAPIPE','INSIGHTFACE','PYTHON'],mark:'CV'},infra:{description:'Self-hosted services and repeatable environments built for control, learning, and reliability.',tags:['UBUNTU SERVER','DOCKER','COMPOSE','PORTAINER','TAILSCALE'],mark:'OS'}};$$('.cap-item').forEach(button=>button.addEventListener('click',()=>{$$('.cap-item').forEach(i=>i.classList.remove('active'));button.classList.add('active');const d=capabilityContent[button.dataset.cap];$('#cap-description').textContent=d.description;$('#cap-tags').innerHTML=d.tags.map(t=>`<span>${t}</span>`).join('');$('.orbit strong').textContent=d.mark}));const cursor=$('.cursor');if(matchMedia('(pointer:fine)').matches){document.addEventListener('mousemove',e=>{cursor.style.left=`${e.clientX}px`;cursor.style.top=`${e.clientY}px`;cursor.classList.add('visible')});$$('[data-cursor]').forEach(el=>{el.addEventListener('mouseenter',()=>{cursor.classList.add('active');$('.cursor span').textContent=el.dataset.cursor});el.addEventListener('mouseleave',()=>{cursor.classList.remove('active');$('.cursor span').textContent='VIEW'})});document.addEventListener('mouseleave',()=>cursor.classList.remove('visible'))}if(!reduceMotion&&matchMedia('(pointer:fine)').matches){const card=$('.hero-card');$('.hero').addEventListener('mousemove',e=>{const x=(e.clientX/innerWidth-.5)*10,y=(e.clientY/innerHeight-.5)*8;card.style.transform=`rotate(${-2+x*.08}deg) translate3d(${x}px,${y}px,0)`});$('.hero').addEventListener('mouseleave',()=>card.style.transform='rotate(-2deg)')}const timeNode=$('#local-time');function updateTime(){timeNode.textContent=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date())+' IST'}updateTime();setInterval(updateTime,30000);$('#year').textContent=new Date().getFullYear();
